const fs = require('fs');
const https = require('https');
const http = require('http');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (skip comments and empty lines)
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('Parsed environment variables:', Object.keys(envVars));

// Prepare the JSON payload
const jsonData = JSON.stringify(envVars, null, 2);

// POST request options
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

console.log(`\nPOSTing to http://localhost:3003/api/doc-export...`);

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`\nResponse status: ${res.statusCode}`);
    console.log(`Response body: ${data}`);
  });
});

req.on('error', (error) => {
  console.error(`Error: ${error.message}`);
});

req.write(jsonData);
req.end();

